function treeGeometry(kind){const b=new GeometryBuilder();b.box('#8b795d',0,1.25,0,.48,2.5,.48);const g=kind===2?new THREE.ConeGeometry(2,4.8,4):kind===1?new THREE.IcosahedronGeometry(2.3,0):new THREE.OctahedronGeometry(2.4,0);b.add(g,['#74a257','#91b56a','#578b61'][kind],0,kind===2?4:3.6,0,1,kind===1?1.05:1,1);g.dispose();return b.build();}
function stopGeometry(){const b=new GeometryBuilder();b.box('#a3a89f',0,1.5,0,.09,3,.09);const g=new THREE.CircleGeometry(.52,8);b.add(g,'#f6f3e9',0,2.6,.055);b.add(g,'#bd554b',0,2.6,.063,.86,.86,1);g.dispose();return b.build();}
function signalGeometry(){const b=new GeometryBuilder();b.box('#858f82',0,2.1,0,.16,4.2,.16).box('#858f82',.75,4.1,0,1.5,.14,.14).box('#dfb653',1.4,3.7,0,.44,1.16,.35);const g=new THREE.CircleGeometry(.13,6);for(let i=0;i<3;i++)b.add(g,['#d5634a','#745e38','#7ba873'][i],1.4,4.02-i*.30,.182);g.dispose();return b.build();}
export function landmarkGeometry(kind){const b=new GeometryBuilder(),wall='#e5dfcb',roof='#89938b',glass='#789698',trim='#f7f1df';
 b.box('#c3c7af',0,.006,0,1,.012,1);
 if(kind==='apartments'){for(const x of [-.24,.24]){b.box(wall,x,.39,0,.40,.78,.59).box(roof,x,.795,0,.43,.05,.62);for(let floor=0;floor<4;floor++)for(const dx of [-.10,.10]){b.plane(glass,x+dx,.12+floor*.18,-.298,.08,.105,0,Math.PI);b.plane(glass,x+dx,.12+floor*.18,.298,.08,.105);}}b.box('#d4c3ac',0,.225,0,.14,.45,.4).box(trim,0,.20,-.32,.10,.025,.13);b.plane(glass,0,.10,-.211,.07,.16,0,Math.PI);for(let x=-.40;x<=.40;x+=.1)b.plane('#f4f0dd',x,.014,-.41,.005,.10,-Math.PI/2);}
 else if(kind==='school'){b.box(wall,0,.25,.22,.82,.50,.29).box(wall,-.31,.185,-.07,.20,.37,.34).box(wall,.31,.185,-.07,.20,.37,.34);b.box(roof,0,.515,.22,.85,.035,.32).box(roof,-.31,.385,-.07,.23,.035,.36).box(roof,.31,.385,-.07,.23,.035,.36);for(let x=-.35;x<.4;x+=.1)b.plane(glass,x,.36,.072,.065,.17,0,Math.PI);b.box('#bbc4b3',0,.01,-.28,.37,.008,.3);for(const z of [-.405,-.16])b.plane(trim,0,.015,z,.31,.006,-Math.PI/2);for(const x of [-.155,.155])b.plane(trim,x,.015,-.283,.006,.25,-Math.PI/2);b.plane(trim,0,.016,-.283,.31,.006,-Math.PI/2);b.box('#9eaa95',-.42,.30,-.34,.008,.6,.008).plane('#d9af61',-.36,.57,-.34,.12,.07);}
 else if(kind==='church'){b.box(wall,0,.24,.08,.50,.48,.66);const g=roofGeometry();b.add(g,roof,0,.48,.08,.57,.20,.70);g.dispose();b.box('#e8dec5',0,.40,-.26,.24,.80,.25);const cone=new THREE.ConeGeometry(1,1,4);b.add(cone,roof,0,.89,-.26,.20,.18,.20,0,Math.PI/4);cone.dispose();b.box(trim,0,1.035,-.26,.014,.13,.014).box(trim,0,1.06,-.26,.072,.012,.014);b.plane('#8b8773',0,.17,-.389,.12,.23,0,Math.PI);const round=new THREE.CircleGeometry(.06,8);b.add(round,glass,0,.56,-.388);round.dispose();for(const x of [-.252,.252])for(const z of [-.08,.12,.30])b.plane(glass,x,.32,z,.075,.22,0,Math.sign(x)*Math.PI/2);}
 if(kind==='industrial'){b.box('#bdc7b8',0,.40,0,.95,.8,.9).box('#82938a',0,.82,0,1,.04,.95);for(const x of [-.25,.25]){b.plane('#9aaca0',x,.25,-.455,.30,.45,0,Math.PI);for(let y=.09;y<.46;y+=.08)b.plane('#6c8173',x,y,-.459,.30,.008,0,Math.PI);}b.plane('#739195',.35,.64,-.456,.15,.15,0,Math.PI);}
 if(kind==='store'||kind==='restaurant'){
  const restaurant=kind==='restaurant';b.box(restaurant?'#dcc3a7':'#d9dccb',0,.40,.07,.9,.8,.72).box(roof,0,.815,.07,.95,.045,.77);
  for(const x of [-.29,.29])b.plane(glass,x,.40,-.293,.28,.38,0,Math.PI);b.plane('#59716c',0,.29,-.298,.13,.55,0,Math.PI);
  b.box(restaurant?'#a95443':'#5e8771',0,.65,-.34,.88,.07,.18).box(trim,0,.755,-.304,.72,.13,.025);
  for(let i=0;i<9;i++)b.box(i%2?'#f6e9c8':restaurant?'#b66f50':'#6b9675',-.4+i*.1,.61,-.39,.09,.018,.2);
  if(restaurant){for(const x of [-.28,.26]){const top=new THREE.CylinderGeometry(.08,.08,.018,8);b.add(top,'#eee2c6',x,.13,-.40);top.dispose();b.box('#7b8770',x,.07,-.40,.02,.14,.02);for(const dx of [-.105,.105])b.box('#8a9a76',x+dx,.06,-.40,.06,.12,.065);}}
  else for(const x of [-.28,.28])b.box('#72915e',x,.04,-.42,.15,.08,.08);
 }
 if(kind==='park'){
  b.box('#789d59',0,.012,0,.98,.014,.98);
  const field=new THREE.CircleGeometry(.46,20);field.rotateX(-Math.PI/2);b.add(field,'#93b567',0,.025,.06,1,1,1);field.dispose();
  const diamond=new THREE.PlaneGeometry(.32,.32);diamond.rotateX(-Math.PI/2).rotateY(Math.PI/4);b.add(diamond,'#cba273',0,.031,-.13);diamond.dispose();
  const bases=[[0,-.355],[.225,-.13],[0,.095],[-.225,-.13]];for(const [x,z]of bases)b.box('#fff6dd',x,.045,z,.025,.014,.025);const mound=new THREE.CylinderGeometry(.026,.03,.014,8);b.add(mound,'#e4c496',0,.041,-.13);mound.dispose();
  for(const side of [-1,1]){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute([0,.04,-.355,side*.44,.04,.085,side*.443,.04,.089,0,.04,-.355,side*.443,.04,.089,.003*side,.04,-.355],3));g.computeVertexNormals();b.add(g,'#f3ebce');g.dispose();}
  for(let i=0;i<13;i++){const a=Math.PI*.1+i*Math.PI*.8/12,x=Math.cos(a)*.46,z=Math.sin(a)*.46; b.box('#6c846a',x,.23,z,.008,.44,.008); }for(const x of [-.32,.32]){b.box('#adaf91',x,.1,-.29,.16,.03,.10).box('#919d80',x,.15,-.245,.16,.04,.025);}
 }
 return b.build();
}
export class TownDressing{
 constructor(root,town,heightAt,options){this.plan=planDressing(town,options);this.group=new THREE.Group();root.add(this.group);this.meshes=[];const material=new THREE.MeshStandardMaterial({vertexColors:true,roughness:1,flatShading:true,side:THREE.DoubleSide});const add=(geometry,items,transform)=>{const m=new THREE.InstancedMesh(geometry,material,items.length),d=new THREE.Object3D();items.forEach((p,i)=>{d.position.set(p.x,heightAt(p.x,p.z),p.z);d.rotation.set(0,p.angle||0,0);d.scale.setScalar(p.scale||1);transform?.(d,p);d.updateMatrix();m.setMatrixAt(i,d.matrix);});m.instanceMatrix.needsUpdate=true;m.computeBoundingSphere();m.castShadow=false;m.receiveShadow=true;this.group.add(m);this.meshes.push(m);return m;};
  for(let kind=0;kind<3;kind++)add(treeGeometry(kind),this.plan.trees.filter(p=>p.kind===kind));add(stopGeometry(),this.plan.stops);add(signalGeometry(),this.plan.signals);
  for(const kind of ['school','apartments','church','park','store','restaurant','industrial']){const items=this.plan.landmarks.filter(p=>p.kind===kind),mesh=add(landmarkGeometry(kind),items,(d,p)=>{d.scale.set(p.width,p.height,p.depth);});mesh.userData.premiseIndices=items.map(p=>town.premises.findIndex(h=>h.id===p.premiseId));if(items.some(p=>p.premiseId))(this.pickMeshes??=[]).push(mesh);}
  const accessGeometry=new GeometryBuilder();for(const p of this.plan.landmarks){if(!p.access)continue;const [a,b]=p.access,dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz),w=p.kind==='park'?2:3.2;if(!len)continue;const nx=-dz/len*w,nz=dx/len*w,vertices=[[a.x+nx,a.z+nz],[a.x-nx,a.z-nz],[b.x-nx,b.z-nz],[a.x+nx,a.z+nz],[b.x-nx,b.z-nz],[b.x+nx,b.z+nz]],g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices.flatMap(([x,z])=>[x,heightAt(x,z)+.2,z]),3));g.computeVertexNormals();accessGeometry.add(g,p.kind==='park'?'#c4c5a9':'#9eaaa6');g.dispose();}if(accessGeometry.positions.length){const m=new THREE.Mesh(accessGeometry.build(),new THREE.MeshStandardMaterial({vertexColors:true,side:THREE.DoubleSide}));this.group.add(m);this.meshes.push(m);}
  // One shared text atlas for all STOP labels, independent of the number of signs.
  if(typeof document!=='undefined'&&this.plan.stops.length){const canvas=document.createElement('canvas');canvas.width=128;canvas.height=64;const ctx=canvas.getContext('2d');if(ctx){ctx.fillStyle='#fff7e9';ctx.font='bold 42px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('STOP',64,32);const texture=new THREE.CanvasTexture(canvas),g=new THREE.PlaneGeometry(.73,.37),m=new THREE.InstancedMesh(g,new THREE.MeshBasicMaterial({map:texture,transparent:true,side:THREE.DoubleSide,depthWrite:false}),this.plan.stops.length),d=new THREE.Object3D();this.plan.stops.forEach((p,i)=>{d.position.set(p.x+Math.sin(p.angle)*.075,heightAt(p.x,p.z)+2.6,p.z+Math.cos(p.angle)*.075);d.rotation.set(0,p.angle,0);d.updateMatrix();m.setMatrixAt(i,d.matrix);});m.instanceMatrix.needsUpdate=true;m.computeBoundingSphere();this.group.add(m);this.meshes.push(m);this.texture=texture;}}
 }
 setVisible(v){this.group.visible=v;}
 stats(){return {dressingTriangles:this.meshes.reduce((s,m)=>s+triangleCount(m.geometry)*(m.count??1),0),dressingBatches:this.meshes.filter(m=>(m.count??1)>0).length,trees:this.plan.trees.length,stopSigns:this.plan.stops.length,trafficLights:this.plan.signals.length,landmarks:this.plan.landmarks.length};}
}
